values ('6d1f0a00-0000-4000-8000-000000002303', '$I = 1$', 'b', null, null, '[{"content":"ប្រើអាំងតេក្រាលដោយផ្នែក៖ ដាក់ $u = x$ និង $dv = e^x \\, dx$ នោះ $du = dx$ និង $v = e^x$។"},{"content":"$I = \\left[x e^x\\right]_0^1 - \\int_0^1 e^x \\, dx = e - \\left[e^x\\right]_0^1$"},{"content":"$I = e - (e - 1) = 1$"}]'::jsonb, 'demo', 'Written for Meh Rean as demo practice content. Not an official MoEYS BacII paper.', 'provisional')
